import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('The Read-Only Input', () => {
  test('Typing updates the input value', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#name');
const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
setter.call(input, 'Aanya');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
if (input.value !== 'Aanya')
  throw new Error('Input did not accept typed value — likely missing onChange');
  });

  test('The display reflects what the user typed', async () => {
    const { container: root } = render(<App />);
    const display = root.querySelector('#display');
if (!display.textContent.includes('Aanya'))
  throw new Error('#display should show "Aanya" — state never updated');
  });
});
